```python
"""A small worker thread that drains a queue.Queue and hands each item to a callback."""

import logging
import queue
import threading

log = logging.getLogger(__name__)

_SHUTDOWN = object()


class QueueWorker:
    """Consume items from a queue in a background thread.

    The callback runs on the worker thread, one item at a time. Exceptions from
    the callback are logged and swallowed so a single bad item can't kill the
    worker.
    """

    def __init__(self, callback, q=None, name="queue-worker", daemon=True):
        self.callback = callback
        self.queue = q if q is not None else queue.Queue()
        self._thread = threading.Thread(target=self._run, name=name, daemon=daemon)
        self._started = False

    def start(self):
        if self._started:
            raise RuntimeError("worker already started")
        self._started = True
        self._thread.start()
        return self

    def put(self, item, block=True, timeout=None):
        self.queue.put(item, block, timeout)

    def _run(self):
        while True:
            item = self.queue.get()
            try:
                if item is _SHUTDOWN:
                    return
                self.callback(item)
            except Exception:
                log.exception("callback failed for item %r", item)
            finally:
                self.queue.task_done()

    def join_queue(self):
        """Block until every item submitted so far has been processed."""
        self.queue.join()

    def stop(self, timeout=None):
        """Ask the worker to finish the backlog and exit, then join the thread."""
        if not self._started:
            return
        self.queue.put(_SHUTDOWN)
        self._thread.join(timeout)

    def __enter__(self):
        return self.start()

    def __exit__(self, *exc):
        self.stop()
        return False


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    with QueueWorker(lambda n: print(f"got {n} -> {n * n}")) as worker:
        for i in range(5):
            worker.put(i)
        worker.join_queue()
```

Notes on the design: the sentinel goes through the queue rather than a flag, so `stop()` drains everything already queued before exiting instead of racing a shutdown check. `task_done()` sits in `finally` so a raising callback doesn't leave `join_queue()` hanging forever. For more than one consumer, run several instances against one shared `q=` and send one sentinel per worker.
